<?php
require_once __DIR__.'/../includes/functions.php';
$token=$_GET['token']??$_POST['token']??''; $error=null; $ok=null;
$st=db()->prepare('SELECT * FROM password_resets WHERE token_hash=? AND expires_at>NOW() AND used_at IS NULL LIMIT 1');$st->execute([hash('sha256',$token)]);$row=$st->fetch();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf($_POST['_csrf']??null);$pass=$_POST['password']??''; if(!$row||strlen($pass)<8)$error='Invalid link or password too short.'; else {db()->prepare('UPDATE users SET password=?, auth_provider=IF(auth_provider="google","google","local") WHERE id=?')->execute([password_hash($pass,PASSWORD_DEFAULT),$row['user_id']]);db()->prepare('UPDATE password_resets SET used_at=NOW() WHERE id=?')->execute([$row['id']]);$ok='Password reset. You can log in now.';}}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Reset password — FluxDrive</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="../assets/css/style.css"></head><body class="auth-page"><div class="auth-card"><a class="brand mb-4" href="index.php"><span class="brand-mark"><i class="bi bi-cloud-arrow-up"></i></span>FluxDrive</a><h1>Choose a new password</h1><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><?php if($ok):?><div class="alert alert-success"><?=e($ok)?></div><a href="login.php" class="btn btn-primary w-100">Login</a><?php elseif($row):?><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="token" value="<?=e($token)?>"><input class="form-control form-control-lg mb-3" type="password" minlength="8" name="password" placeholder="New password" required><button class="btn btn-primary btn-lg w-100">Reset password</button></form><?php else:?><div class="alert alert-danger">This reset link is invalid or expired.</div><?php endif;?></div></body></html>
